// Deterministic snapshot of the supplied local references. Run only when authoring this migration.
import { readFileSync, writeFileSync } from "node:fs";
const read = (name) =>
  JSON.parse(
    readFileSync(
      new URL(`../src/address/${name}.json`, import.meta.url),
      "utf8",
    ),
  );
let sql = `-- Supplied Philippine references; no external service and no postal-code lookup.
-- Generated by scripts/generate-address-migration.mjs; applied migrations remain immutable.
create function app_private.address_name(v text) returns text language sql immutable set search_path = '' as $$
 select regexp_replace(regexp_replace(lower(trim(coalesce(v,''))), '^city of\\s+', ''), '\\s+city$', '');
$$;
create table app_private.address_provinces(code text primary key, name text not null, normalized text generated always as(app_private.address_name(name)) stored);
create table app_private.address_cities(code text primary key, name text not null, province_code text references app_private.address_provinces(code), normalized text generated always as(app_private.address_name(name)) stored);
create table app_private.address_barangays(code text primary key, name text not null, city_code text not null references app_private.address_cities(code), normalized text generated always as(app_private.address_name(name)) stored);
`;
for (const [file, table, columns, transform] of [
  [
    "provinces",
    "provinces",
    "code text,name text",
    (x) => ({ code: x.code, name: x.name }),
  ],
  [
    "cities",
    "cities",
    "code text,name text,province_code text",
    (x) => ({ code: x.code, name: x.name, province_code: x.provinceCode }),
  ],
  [
    "barangay-search-index",
    "barangays",
    "code text,name text,city_code text",
    (x) => ({ code: x.code, name: x.name, city_code: x.cityCode }),
  ],
]) {
  const rows = read(file).map(transform),
    names = columns
      .split(",")
      .map((c) => c.split(" ")[0])
      .join(",");
  for (let i = 0; i < rows.length; i += 1000)
    sql += `insert into app_private.address_${table}(${names}) select ${names} from jsonb_to_recordset($reference$${JSON.stringify(rows.slice(i, i + 1000))}$reference$::jsonb) as r(${columns});\n`;
}
sql += `create index on app_private.address_provinces(normalized);
create index on app_private.address_cities(normalized,province_code);
create index on app_private.address_barangays(city_code,normalized);
alter table app_private.address_provinces enable row level security;
alter table app_private.address_cities enable row level security;
alter table app_private.address_barangays enable row level security;
revoke all on all tables in schema app_private from public,anon,authenticated;
`;
// Preserve the authorization sources of existing fields when relocating them.
// Newly created Address fields do not receive any legacy group's permissions.
sql += `create table app_private.address_legacy_groups(field_id uuid primary key references public.field_definitions(id), group_id uuid not null references public.field_groups(id), destination_group uuid not null references public.field_groups(id));
alter table app_private.address_legacy_groups enable row level security;
revoke all on app_private.address_legacy_groups from public,anon,authenticated;
`;
for (const [file, functionName] of [
  ["20261010001200_explainable_permission_decisions.sql", "field_decision"],
]) {
  const source = readFileSync(
    new URL(`../supabase/migrations/${file}`, import.meta.url),
    "utf8",
  );
  const start = source.indexOf(`create function app_private.${functionName}(`);
  const end = source.indexOf("end $$;", start) + 7;
  let definition = source
    .slice(start, end)
    .replace(/^create function/, "create or replace function");
  definition = definition.replace(
    "p.group_id=f.group_id",
    "(p.group_id=f.group_id or exists(select 1 from app_private.address_legacy_groups l join public.field_groups old_group on old_group.id=l.group_id and old_group.active where l.field_id=f.id and l.destination_group=f.group_id and l.group_id=p.group_id))",
  );
  sql += definition + "\n";
}
const definitions = read("defaultFields");
sql += `-- Reuse existing keys and field IDs; no employee values or explicit field grants are rewritten.
do $$ declare g uuid; f record; existing_id uuid; begin
 select id into g from public.field_groups where normalized_name=app_private.normalized('Address');
 if g is null then insert into public.field_groups(name,description,display_order) values('Address','Home and current Philippine addresses and emergency contact.',30) returning id into g; end if;
 for f in select * from jsonb_to_recordset($definitions$${JSON.stringify(definitions)}$definitions$::jsonb) as d(key text,label text,type text,options jsonb) loop
   select id into existing_id from public.field_definitions where key=f.key or
     (f.key='emergency_contact_name' and key='emergency_name') or
     (f.key='emergency_contact_number' and key='emergency_phone') or
     (f.key='emergency_contact_relationship' and key='emergency_relationship') order by (key=f.key) desc,id limit 1;
   if existing_id is null then
     insert into public.field_definitions(group_id,key,label,type,options,display_order) values(g,f.key,f.label,f.type,f.options,case when f.key like 'current_%' then 20 when f.key like 'emergency_%' then 30 else 10 end);
   else
     -- Existing types, required rules, applicability, sensitivity and explicit grants stay intact.
     insert into app_private.address_legacy_groups(field_id,group_id,destination_group) select id,group_id,g from public.field_definitions where id=existing_id and group_id<>g on conflict do nothing;
     update public.field_definitions set group_id=g,active=active and exists(select 1 from public.field_groups where id=group_id and active) where id=existing_id;
     if f.type='select' then update public.field_definitions set options=(select jsonb_agg(distinct value) from jsonb_array_elements(options || f.options)) where id=existing_id and type='select'; end if;
   end if;
 end loop;
 -- Move any legacy emergency-contact definitions without renaming their immutable keys.
 insert into app_private.address_legacy_groups(field_id,group_id,destination_group) select id,group_id,g from public.field_definitions where group_id<>g and (key like 'emergency_contact_%' or key in ('emergency_name','emergency_phone','emergency_relationship')) on conflict do nothing;
 update public.field_definitions set group_id=g,active=active and exists(select 1 from public.field_groups where id=group_id and active) where key like 'emergency_contact_%' or key in ('emergency_name','emergency_phone','emergency_relationship');
end $$;
create function app_private.validate_address(v jsonb,prefix text) returns void language plpgsql stable set search_path = '' as $$
declare p text := app_private.address_name(v->>(prefix||'province')); c text := app_private.address_name(v->>(prefix||'city_municipality')); b text := app_private.address_name(v->>(prefix||'barangay')); pc text; cc text; begin
 if p<>'' then select code into pc from app_private.address_provinces where normalized=p; if pc is null then raise exception 'Choose a province from the official list.' using errcode='22023'; end if; end if;
 if c<>'' then select code into cc from app_private.address_cities where normalized=c and province_code is not distinct from pc; if cc is null then raise exception 'Choose a city and its matching province from the official list.' using errcode='22023'; end if; end if;
 if b<>'' and (cc is null or not exists(select 1 from app_private.address_barangays where city_code=cc and normalized=b)) then raise exception 'Choose a barangay within the selected city or municipality.' using errcode='22023'; end if;
end $$;
create function app_private.validate_employee_addresses() returns trigger language plpgsql set search_path = '' as $$
declare prefix text; key text; touched boolean; begin
 foreach prefix in array array['','current_'] loop
   touched := TG_OP='INSERT';
   if TG_OP='UPDATE' then foreach key in array array['address','province','city_municipality','barangay','postal_code'] loop touched := touched or ((new.custom_values->(prefix||key)) is distinct from (old.custom_values->(prefix||key))); end loop; end if;
   if touched then perform app_private.validate_address(new.custom_values,prefix); end if;
 end loop;
 return new;
end $$;
create trigger employee_official_addresses before insert or update of custom_values on public.employees for each row execute function app_private.validate_employee_addresses();
revoke all on function app_private.address_name(text),app_private.validate_address(jsonb,text),app_private.validate_employee_addresses() from public,anon,authenticated;
`;
writeFileSync(
  new URL(
    "../supabase/migrations/20261011000200_default_addresses.sql",
    import.meta.url,
  ),
  sql,
);
